def main(out_dir):
    out = Path(out_dir)
    codes = {r["code"] for r in csv.DictReader(open(out / "competencies.csv", encoding="utf-8"))}
    ids = set()
    for t in TOPICS:
        assert t[0] not in ids, t[0]
        ids.add(t[0])
        for code in t[3:6]:
            assert code == "" or code in codes, (t[0], code)
    with open(out / "topics.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["topic_id", "name", "speech_examples", "manual", "auto", "load", "basis"])
        w.writerows(TOPICS)
    used = {c for t in TOPICS for c in t[3:6] if c}
    print("тем:", len(TOPICS), "| без компетенции:", sum(1 for t in TOPICS if not any(t[3:6])))
    print("компетенции без темы:", ", ".join(sorted(codes - used)))


if __name__ == "__main__":
    main(sys.argv[1])
